// Parse AI analysis and prepare update data

const combined = $('Combine Email + Lead Data').item.json;
const aiResponse = $input.first().json;

let analysis = {
  interest_level: 'WARM',
  motivation_score: 50,
  sentiment: 'neutral',
  key_info_extracted: {},
  motivation_signals: [],
  objections: [],
  red_flags: [],
  next_action: 'Follow up in 2-3 days',
  suggested_response: null,
  call_readiness: 'needs_nurturing',
  summary: 'Response received, analysis pending review'
};

try {
  const content = aiResponse.choices[0].message.content;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = { ...analysis, ...JSON.parse(jsonMatch[0]) };
  }
} catch (e) {
  console.log('AI parse error:', e);
}

// Map interest level to status
const statusMap = {
  'COLD': 'Cold',
  'WARM': 'Warm',
  'HOT': 'HOT'
};

return [{
  json: {
    leadId: combined.leadId,
    email: combined.email,
    context: combined.context,
    analysis: analysis,
    newStatus: statusMap[analysis.interest_level] || 'Warm',
    updateFields: {
      'Status': statusMap[analysis.interest_level] || 'Warm',
      'AI Score': analysis.motivation_score,
      'Response Analysis': JSON.stringify(analysis, null, 2),
      'Last Response Date': new Date().toISOString(),
      'Call Readiness': analysis.call_readiness
    }
  }
}];

